import { useState } from 'react';

function Register() {
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    password: '',
    password_confirmation: '' // Добавим подтверждение пароля
  });

  const [message, setMessage] = useState('');
  const [errors, setErrors] = useState({});
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
    // Очищаем ошибку при изменении поля
    if (errors[e.target.name]) {
      setErrors({ ...errors, [e.target.name]: null });
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setIsSubmitting(true);
    setMessage('');
    setErrors({});

    try {
      const response = await fetch('http://127.0.0.1:8000/api/register', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        },
        body: JSON.stringify(formData)
      });

      const data = await response.json();

      if (!response.ok) {
        // Обработка ошибок валидации (422)
        if (response.status === 422) {
          setErrors(data.errors || {});
          setMessage(data.message || 'Пожалуйста, исправьте ошибки в форме');
        } else {
          setMessage(data.message || 'Произошла ошибка при регистрации');
        }
        return;
      }

      // Успешная регистрация
      setMessage('Регистрация прошла успешно! Перенаправляем...');
      setFormData({
        name: '',
        email: '',
        password: '',
        password_confirmation: ''
      });

      // Редирект или другие действия после успешной регистрации
      // window.location.href = '/dashboard';

    } catch (error) {
      setMessage('Ошибка соединения с сервером');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label>Имя:</label>
        <input
          name="name"
          value={formData.name}
          onChange={handleChange}
          required
        />
        {errors?.name && <div className="error">{errors.name[0]}</div>}
      </div>

      <div>
        <label>Email:</label>
        <input
          name="email"
          type="email"
          value={formData.email}
          onChange={handleChange}
          required
        />
        {errors?.email && <div className="error">{errors.email[0]}</div>}
      </div>

      <div>
        <label>Пароль:</label>
        <input
          name="password"
          type="password"
          value={formData.password}
          onChange={handleChange}
          required
          minLength="6"
        />
        {errors?.password && <div className="error">{errors.password[0]}</div>}
      </div>

      <div>
        <label>Подтвердите пароль:</label>
        <input
          name="password_confirmation"
          type="password"
          value={formData.password_confirmation}
          onChange={handleChange}
          required
          minLength="6"
        />
      </div>

      <button 
        type="submit" 
        disabled={isSubmitting}
      >
        {isSubmitting ? 'Регистрация...' : 'Зарегистрироваться'}
      </button>

      {message && (
        <div className={errors ? 'error-message' : 'success-message'}>
          {message}
        </div>
      )}
    </form>
  );
}

export default Register;
